{
  "$schema": "https://schema.tauri.app/config/2",
  "productName": "NMSBT",
  "version": "26.9.3",
  "identifier": "dev.gloved.nms-base-tool",
  "build": {
    "beforeDevCommand": "bun run dev",
    "devUrl": "http://localhost:1420",
    "beforeBuildCommand": "bun run build",
    "frontendDist": "../build"
  },
  "app": {
    "windows": [
      {
        "title": "NMSBT",
        "width": 1200,
        "height": 800,
        "center": true,
        "scrollBarStyle": "fluentOverlay"
      }
    ],
    "security": {
      "csp": null
    }
  },
  "bundle": {
    "createUpdaterArtifacts": true,
    "category": "Utility",
    "windows": {
      "allowDowngrades": true,
      "nsis": {
        "installerIcon": "icons/icon.ico"
      },
      "webviewInstallMode": {
        "silent": true,
        "type": "downloadBootstrapper"
      }
    },
    "linux": {
      "appimage": {
        "bundleMediaFramework": false,
        "files": {}
      },
      "deb": {
        "files": {}
      },
      "rpm": {
        "epoch": 0,
        "files": {},
        "release": "1"
      }
    },
    "macOS": {
      "minimumSystemVersion": "12.0"
    },
    "homepage": "https://github.com/TheGloved1/nms-base-tool",
    "active": true,
    "targets": [
      "msi",
      "deb",
      "appimage",
      "rpm",
      "app",
      "dmg"
    ],
    "icon": [
      "icons/32x32.png",
      "icons/128x128.png",
      "icons/128x128@2x.png",
      "icons/icon.icns",
      "icons/icon.ico"
    ]
  },
  "plugins": {
    "updater": {
      "endpoints": [
        "https://github.com/TheGloved1/nms-base-tool/releases/latest/download/updater.json"
      ],
      "pubkey": "dW50cnVzdGVkIGNvbW1lbnQ6IG1pbmlzaWduIHB1YmxpYyBrZXk6IEI2RTI5MDZBRTU5MTAwOUMKUldTY0FKSGxhcERpdGpTaXFOd0o3QytqcmpzbEg0dmRwczJQVmdvczQvQ2QycWowVFF3S3lEem0K"
    }
  }
}
